def calculator(expr):
    return eval(expr)

def get_weather(city):
    return f"{city}: 24C, clear skies"

def production_agent(task, memory, log, call_count):
    call_count[0] += 1
    import time
    log.append({"time": time.strftime("%H:%M:%S"), "task": task})
    try:
        if task.startswith("calc:"):
            expr = task.split(":", 1)[1].strip()
            result = calculator(expr)
            return {"task": task, "result": result, "status": "ok"}
        elif task.startswith("weather:"):
            city = task.split(":", 1)[1].strip()
            result = get_weather(city)
            return {"task": task, "result": result, "status": "ok"}
        elif task.startswith("remember:"):
            rest = task.split(":", 1)[1].strip()
            if " is " in rest:
                key, value = rest.split(" is ", 1)
                memory[key.strip()] = value.strip()
                return {"task": task, "result": f"Stored {key.strip()}", "status": "ok"}
            return {"task": task, "result": "Format: remember: X is Y", "status": "error"}
        elif task.startswith("recall:"):
            key = task.split(":", 1)[1].strip()
            result = memory.get(key, "Not found")
            return {"task": task, "result": result, "status": "ok"}
        elif task == "stats":
            return {"task": task, "result": f"Total calls: {call_count[0]}", "status": "ok"}
        elif task == "log":
            return {"task": task, "result": log, "status": "ok"}
        else:
            return {"task": task, "result": "Unknown command", "status": "error"}
    except Exception as e:
        return {"task": task, "result": f"Error: {str(e)}", "status": "error"}
